from .clock import hour_bucket
def aggregate_hour_samples(samples):
    totals = {}
    for timestamp, amount in samples:
        bucket = hour_bucket(timestamp)
        totals[bucket] = totals.get(bucket, 0) + amount
    return sorted(totals.items())

