import unittest
from reservoir.summary import aggregate_hour_samples
from reservoir.clock import hour_bucket
class HourSummaryTests(unittest.TestCase):
    def test_partial_bucket_keeps_last_sample(self):
        result = aggregate_hour_samples([(3660, 4), (7190, 7), (7260, 3)])
        self.assertEqual(result, [(3600, 11), (7200, 3)])
    def test_hour_boundary(self):
        self.assertEqual(hour_bucket(7200), 7200)
if __name__ == '__main__':
    unittest.main()
